from pathlib import Path
import json
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
P=Path(__file__).resolve().parent
b=json.loads((P/'BENCHMARK.json').read_text());a=json.loads((P/'ALLOCATION.json').read_text())
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
f,axes=plt.subplots(1,2,figsize=(11,4),layout='constrained')
x=list(range(4));v=[c['milliseconds']['paired_median_saving'] for c in b['cases']];ci=[c['milliseconds']['paired_bootstrap_median_95ci'] for c in b['cases']]
axes[0].errorbar(x,v,yerr=[[y-z[0] for y,z in zip(v,ci)],[z[1]-y for y,z in zip(v,ci)]],fmt='o',capsize=5,color='#2363a1');axes[0].axhline(0,color='#777',linewidth=1);axes[0].set_xticks(x,['1×64KiB','4×64KiB','1×4MiB','1×16MiB']);axes[0].set_ylabel('Paired median saving (ms), 95% CI');axes[0].set_title('Loopback Copy latency, 21 pairs')
x=[0,1];old=[c['requested_allocation_bytes_before_median']/2**20 for c in a['cases']];new=[c['requested_allocation_bytes_after_median']/2**20 for c in a['cases']]
axes[1].bar([i-.18 for i in x],old,.36,label='Before',color='#a9b8c9');axes[1].bar([i+.18 for i in x],new,.36,label='After',color='#2363a1');axes[1].set_xticks(x,['4MiB Copy','16MiB Copy']);axes[1].set_ylabel('Median cumulative requested allocation (MiB)');axes[1].set_title('One full payload allocation removed');axes[1].legend(frameon=False)
f.savefig(P/'results.png',dpi=150);f.savefig(P/'results.svg');plt.close(f)
rows=''.join('<tr>'+''.join(f'<td>{v}</td>' for v in [c['case'],f"{c['milliseconds']['before_median']:.3f}",f"{c['milliseconds']['after_median']:.3f}",f"{c['milliseconds']['paired_median_saving']:.3f}",str([round(v,3) for v in c['milliseconds']['paired_bootstrap_median_95ci']]),f"{c['milliseconds']['two_sided_sign_test_p']:.5g}"] )+'</tr>' for c in b['cases'])
alloc=''.join(f"<tr><td>{c['bytes']//2**20}MiB</td><td>{c['requested_allocation_bytes_before_median']:,}</td><td>{c['requested_allocation_bytes_after_median']:,}</td><td>{c['paired_median_bytes_saved']:,}</td><td>{c['bootstrap_median_95ci']}</td><td>{c['peak_heap_before_median']:,} → {c['peak_heap_after_median']:,}</td></tr>" for c in a['cases'])
svg=(P/'results.svg').read_text();svg=svg[svg.index('<svg'):]
(P/'results.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Forwarded attachment allocation profile</title><style>body{font:16px/1.5 system-ui,sans-serif;color:#15263c;background:#f5f7fa;max-width:1100px;margin:32px auto;padding:0 20px}svg{width:100%;height:auto;background:white}table{border-collapse:collapse;background:white;width:100%;font-size:14px;margin:20px 0}th,td{padding:9px;border-bottom:1px solid #d6dee8;text-align:left}h1{font-size:27px}p{max-width:90ch}.note{color:#40536d}</style><h1>Forwarded attachments avoid one full payload copy</h1><p>Actual production Copy/fetch/serial-send bodies with generated loopback HTTP data. Forwarding passes reusable response Bytes directly to the PUT body. All scheduling, Path buffering, authentication, error and redirect behavior stays serial.</p>'''+svg+'''<p class="note">Rust dev profile (opt0/debug0), fixed 12ms per local GET/PUT, 21 randomized pairs per case. Only the 16MiB latency confidence interval excludes zero. This is not app, device, Internet or production latency.</p><h2>Latency (milliseconds)</h2><table><tr><th>Case</th><th>Before</th><th>After</th><th>Paired saving</th><th>95% CI</th><th>Sign-test p</th></tr>'''+rows+'''</table><h2>Allocation traffic (bytes)</h2><table><tr><th>Payload</th><th>Before median</th><th>After median</th><th>Paired saving</th><th>95% CI</th><th>Peak heap before → after</th></tr>'''+alloc+'''</table><p>Allocation counts sum requested sizes of successful alloc/realloc calls, including local HTTP collaborators; these are not RSS or a direct byte-copy counter. Payload-sized events were 2 before and 1 after in all 21 pairs per size. Peak heap does not materially improve because response accumulation sets the maximum. Copy sources can be unbounded; the unchanged serial flow retains at most one payload pipeline.</p><p>Separate allocation repetitions ran on a shared host and make no latency claim. Full receipts, samples, hashes and metadata are in BENCHMARK.json and ALLOCATION.json. The 307 controls and actual per-chat queue regressions remain runnable with check.py. Streaming and two-job experimental candidates were withheld.</p></html>''')
